-- Seed: full BOM catalogue, all work centres, extracted from
-- 'Copy of BOMS for Alyssa (003).xlsx' (Data sheet), 2026-07-29.
-- Supersedes/subsumes blender_bom_seed.sql's rows (same table, same
-- (bom_id, line_nbr) keys) -- re-running this is safe: existing rows
-- just get their descriptive fields refreshed, ingredient_column is
-- left alone so Blends-page corrections survive. ingredient_column is
-- intentionally NULL here for every row -- Blender rows resolve it at
-- read time via lib/production/bom.ts's matchColumn() fallback; every
-- other work centre has no A-F concept at all.
on conflict (bom_id, line_nbr) do update set
  output_item_id = excluded.output_item_id,
  output_description = excluded.output_description,
  work_centre = excluded.work_centre,
  component_item_id = excluded.component_item_id,
  component_description = excluded.component_description,
  qty_required = excluded.qty_required,
  warehouse = excluded.warehouse,
  uom = excluded.uom,
  updated_at = now();
